using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading.Tasks;
using ParoleRP;
class EngineDeadlineTests {
 static int count;static string root,fake;const string key="FAKE_SECRET_KEY_NOT_SENT_TO_A_PROVIDER";
 static void Check(bool valid,string name){if(!valid)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static string Case(string name,string flag){string folder=Path.Combine(root,name+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);File.Copy(fake,Path.Combine(folder,"FakeEngine.exe"));if(flag!=null)File.WriteAllText(Path.Combine(folder,flag),"");return folder;}
 static int Lines(string folder,string name){string p=Path.Combine(folder,name);return File.Exists(p)?File.ReadAllLines(p).Length:0;}
 static async Task<Exception> Failure(Task task){try{await task;return null;}catch(Exception e){return e;}}
 static async Task Bounded(Task task,int ms=15000){if(await Task.WhenAny(task,Task.Delay(ms))!=task)throw new Exception("Test hung beyond its deadline.");}
 static async Task WaitForStart(string folder){for(int i=0;i<150&&Lines(folder,"starts.txt")==0;i++)await Task.Delay(20);Check(Lines(folder,"starts.txt")>0,"fake worker actually started");}
 static async Task Gone(string folder){for(int i=0;i<150;i++){bool alive=false;foreach(string id in File.ReadAllLines(Path.Combine(folder,"starts.txt"))){try{using(var p=Process.GetProcessById(Int32.Parse(id))){if(!p.HasExited&&String.Equals(p.MainModule.FileName,Path.Combine(folder,"FakeEngine.exe"),StringComparison.OrdinalIgnoreCase))alive=true;}}catch{}}if(!alive){Check(true,"only owned fake workers cleaned up");return;}await Task.Delay(20);}throw new Exception("Fake worker left alive.");}
 static async Task TimeoutCase(string name,string flag,bool large,bool production){string folder=Case(name,flag);var api=production?new GroqApi(Path.Combine(folder,"FakeEngine.exe")):new GroqApi(Path.Combine(folder,"FakeEngine.exe"),1400);var traces=new List<EngineTrace>();var reports=new List<ApiReport>();api.Diagnostic+=traces.Add;api.Reported+=reports.Add;var c=new Character();if(large){c.Context=new string('x',4500);c.Words=String.Join("\n",Enumerable.Range(0,170).Select(i=>"mot"+i+new string('y',90)));}DataFiles.ValidateCharacter(c);var timer=Stopwatch.StartNew();try{Task pending=api.Correct(key,"qwen/qwen3.8-27b",c,"","Phrase factice.");var failure=Failure(pending);await Bounded(failure);var error=await failure;Check(error!=null&&error.Message.Contains("Délai"),name+" times out with an explained error");Check(timer.ElapsedMilliseconds<(production?14000:6000),name+" total exchange is bounded");if(production)Check(timer.ElapsedMilliseconds>=9000,"production budget stays at ten seconds, not two");Check(traces.Count==1&&traces[0].Outcome==EngineOutcome.Timeout,name+" reports timeout metadata");Check(traces[0].Stage==(flag=="noread.flag"?(large?EngineStage.Send:EngineStage.Flush):EngineStage.Read),name+" identifies blocked stage");Check(reports.Count==1&&!reports[0].ok&&reports[0].usageEvents==null,name+" local failure counted without fabricated tokens");Check(Lines(folder,"starts.txt")==1,name+" no automatic request replay");Correction corrected=null;try{corrected=await api.Correct(key,"qwen/qwen3.8-27b",new Character(),"","Phrase factice.");}catch{string crash=Path.Combine(folder,"crash.txt");if(File.Exists(crash))Console.Error.WriteLine(File.ReadAllText(crash));throw;}Check(corrected.Text=="Phrase factice.",name+" next explicit request succeeds");Check(Lines(folder,"starts.txt")==2,name+" replacement worker starts cleanly");Check(!String.Join(" ",traces.Select(t=>t.Operation+" "+t.Stage+" "+t.Outcome)).Contains(key),"diagnostic metadata excludes credentials");}finally{api.Dispose();}await Gone(folder);}
 static async Task Protocol(){string folder=Case("invalid-frame","bad.flag");using(var api=new GroqApi(Path.Combine(folder,"FakeEngine.exe"),1800)){var failed=await Failure(api.Test(key,"qwen/qwen3.8-27b"));Check(failed!=null,"incomplete response rejected");await api.Test(key,"qwen/qwen3.8-27b");Check(Lines(folder,"starts.txt")==2,"invalid protocol retires old channel");}await Gone(folder);}
 static async Task Quota(){string folder=Case("provider-quota","quota.flag");using(var api=new GroqApi(Path.Combine(folder,"FakeEngine.exe"),1800)){var error=await Failure(api.Test(key,"qwen/qwen3.8-27b"));Check(error!=null&&error.Message.Contains("quota"),"provider quota message preserved");Check(Lines(folder,"requests.txt")==1,"provider errors are not replayed");await api.Test(key,"qwen/qwen3.8-27b");Check(Lines(folder,"starts.txt")==1,"valid provider errors keep healthy protocol channel");}await Gone(folder);}
 static async Task DisposeQueued(){string folder=Case("dispose-queued","noread.flag");var api=new GroqApi(Path.Combine(folder,"FakeEngine.exe"),5000);var first=Failure(api.Test(key,"qwen/qwen3.8-27b"));await WaitForStart(folder);var second=Failure(api.Test(key,"qwen/qwen3.8-27b"));api.Dispose();await Bounded(Task.WhenAll(first,second),3000);Check(await first!=null&&await second!=null,"disposal unblocks active and queued request");Check(Lines(folder,"starts.txt")==1,"queued request never starts worker after disposal");await Gone(folder);}
 static async Task ChildCleanup(){string folder=Case("bootloader-child","child.flag");using(var api=new GroqApi(Path.Combine(folder,"FakeEngine.exe"),2200)){var error=await Failure(api.Test(key,"qwen/qwen3.8-27b"));Check(error!=null&&error.Message.Contains("Délai"),"bootloader-style parent is bounded");Check(Lines(folder,"starts.txt")==2,"owned fake engine child was spawned");}await Gone(folder);}
 static async Task LogPrivacy(){string folder=Path.Combine(root,"logs-"+Guid.NewGuid().ToString("N"));EngineDiagnostics.Request(folder,new EngineTrace{Operation=key,Stage=EngineStage.Send,Outcome=EngineOutcome.Timeout,Milliseconds=1400});string path=Path.Combine(folder,"diagnostic.log");for(int i=0;i<100&&!File.Exists(path);i++)await Task.Delay(20);string log=File.ReadAllText(path);Check(log.Contains("op=unknown")&&!log.Contains(key),"on-disk diagnostics reject credential-like operation names");}
 static async Task Run(string[] args){root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);fake=Path.GetFullPath(args[1]);await TimeoutCase("small-flush","noread.flag",false,true);await TimeoutCase("large-send","noread.flag",true,false);await TimeoutCase("read-stall","noreply.flag",false,false);await TimeoutCase("partial-line","partial.flag",false,false);await Protocol();await Quota();await DisposeQueued();await ChildCleanup();await LogPrivacy();Console.WriteLine(count+" engine transport checks passed. No real API request or UI input.");}
 static int Main(string[] args){try{Run(args).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
